  <div class="col-md-8"><label class="form-label">Nombre de la promoción</label><input name="nombre" class="form-control" maxlength="120" required value="<?= e(old('nombre', $p['nombre'] ?? '')) ?>" placeholder="Ej. Especial Día de la Madre"></div>
  <div class="col-md-4"><label class="form-label">Descuento (%)</label><input name="porcentaje" type="number" min="1" max="100" step="1" class="form-control" required value="<?= e(old('porcentaje', isset($p['porcentaje_descuento']) ? (int) $p['porcentaje_descuento'] : '')) ?>"></div>
  <div class="col-md-4"><label class="form-label">Desde</label><input name="inicio" type="date" class="form-control" required value="<?= e(old('inicio', $p['fecha_inicio'] ?? date('Y-m-d'))) ?>"></div>
  <div class="col-md-4"><label class="form-label">Hasta</label><input name="fin" type="date" class="form-control" required value="<?= e(old('fin', $p['fecha_fin'] ?? '')) ?>"></div>
